mapper.select:
select  

     and t.title like concat('%', #{q}, '%') 
     and t.status = #{status} 
     and t.priority = #{priority} 
     and t.assignee_user_id = #{assigneeUserId} 
     and t.created_by_user_id = #{createdByUserId} 

        and (t.assignee_user_id = #{ownedByUserId} or t.created_by_user_id = #{ownedByUserId})


order by
    field(t.status, 'IN_PROGRESS', 'PENDING', 'COMPLETED', 'APPROVED', 'CANCELLED'),
    field(t.priority, 'HIGH', 'MEDIUM', 'LOW'),
    (t.due_date is null), t.due_date asc, t.id desc
